/**
 * AD20 — Run the report types published in the backend catalogue. JSON is
 * previewed in-app; CSV and PDF are generated by the same authorised report
 * service so the downloaded result matches the selected filters.
 */
import { ApiError } from '../api/ApiError';

const LABELS = {
  ENROLMENTS: 'Enrolments',
  ATTENDANCE: 'Attendance',
  TEACHING_ASSIGNMENTS: 'Teaching assignments',
  ASSESSMENT_COMPLETENESS: 'Assessment completeness',
  PUBLISHED_BROADSHEET: 'Published broadsheet',
  SUBJECT_MARKS: 'Assigned subject marks',
};

export class ReportsPresenter {
  constructor(reportsModel) {
    this.model = reportsModel;
    this._render = null;
    this._navigation = null;
    this._alive = false;
    this.initialState = {
      status: 'loading',
      catalogue: [],
      formats: ['JSON', 'CSV', 'PDF'],
      maximumRows: 1000,
      options: {
        sessions: [],
        terms: [],
        classes: [],
        students: [],
        cycles: [],
        assignments: [],
      },
      kind: '',
      filters: {},
      report: null,
      working: false,
      errorText: null,
      notice: null,
    };
    this.state = this.initialState;
  }

  attach(render, navigation) {
    this._render = render;
    this._navigation = navigation;
    this._alive = true;
  }

  detach() {
    this._alive = false;
  }

  _setState(patch) {
    if (!this._alive || !this._render) return;
    this.state = { ...this.state, ...patch };
    this._render(this.state);
  }

  async load() {
    this._setState({ status: 'loading', errorText: null });
    try {
      const [catalogue, options] = await Promise.all([
        this.model.catalogue(),
        this.model.options(),
      ]);
      const entries = Array.isArray(catalogue?.items) ? catalogue.items : [];
      const kind = entries[0]?.kind ?? '';
      this._setState({
        status: 'content',
        catalogue: entries.map((item) => ({
          ...item,
          label: LABELS[item.kind] ?? item.kind,
        })),
        formats: catalogue.formats ?? ['JSON', 'CSV', 'PDF'],
        maximumRows: catalogue.maximumRows ?? 1000,
        options,
        kind,
        filters: options.activeSessionId
          ? { sessionId: options.activeSessionId }
          : {},
        report: null,
        errorText: null,
      });
    } catch (error) {
      this._setState({
        status: 'error',
        errorText: error instanceof ApiError ? error.message : error?.message ?? 'Could not load the report catalogue and filters.',
      });
    }
  }

  onRetry() {
    return this.load();
  }

  selectKind(kind) {
    const entry = this.state.catalogue.find((item) => item.kind === kind);
    if (!entry) return;
    const filters = {};
    if (entry.filters?.includes('sessionId') && this.state.options.activeSessionId) {
      filters.sessionId = this.state.options.activeSessionId;
    }
    this._setState({ kind, filters, report: null, errorText: null, notice: null });
  }

  setFilter(name, value) {
    const filters = { ...this.state.filters };
    if (value === undefined || value === null || value === '') delete filters[name];
    else filters[name] = value;

    // When session changes, do not retain a term from another academic session.
    if (name === 'sessionId' && filters.termId) {
      const term = this.state.options.terms.find((item) => item.value === filters.termId);
      const session = this.state.options.sessions.find((item) => item.value === value);
      if (term && session && !term.label.startsWith(session.label)) delete filters.termId;
    }
    this._setState({ filters, report: null, errorText: null, notice: null });
  }

  selectedEntry() {
    return this.state.catalogue.find((item) => item.kind === this.state.kind) ?? null;
  }

  async run() {
    if (!this.state.kind || this.state.working) return false;
    const entry = this.selectedEntry();
    const filters = this.state.filters;
    const required = entry?.requiredFilters ?? [];
    const missing = required.filter((name) => !filters[name]);
    if (missing.length) {
      this._setState({
        errorText: 'Choose the required report filters: ' + missing.join(', ') + '.',
      });
      return false;
    }
    if (this.state.kind === 'ATTENDANCE' && !filters.termId && (!filters.from || !filters.to)) {
      this._setState({ errorText: 'Attendance reports need a term or both date boundaries.' });
      return false;
    }

    this._setState({ working: true, errorText: null, notice: null, report: null });
    try {
      const report = await this.model.run(this.state.kind, filters);
      this._setState({
        working: false,
        report,
        notice: (report.complete ? 'Complete report' : 'Report generated') +
          ' · ' + report.rowCount + ' rows',
      });
      return true;
    } catch (error) {
      this._setState({
        working: false,
        errorText: error instanceof ApiError ? error.message : error?.message ?? 'The report could not be generated.',
      });
      return false;
    }
  }

  async export(format) {
    if (!this.state.kind || this.state.working) return null;
    const entry = this.selectedEntry();
    const required = entry?.requiredFilters ?? [];
    const missing = required.filter((name) => !this.state.filters[name]);
    if (missing.length) {
      this._setState({ errorText: 'Choose the required report filters: ' + missing.join(', ') + '.' });
      return null;
    }
    if (this.state.kind === 'ATTENDANCE' &&
        !this.state.filters.termId &&
        (!this.state.filters.from || !this.state.filters.to)) {
      this._setState({ errorText: 'Attendance reports need a term or both date boundaries.' });
      return null;
    }
    this._setState({ working: true, errorText: null, notice: null });
    try {
      const file = await this.model.download(this.state.kind, this.state.filters, format);
      this._setState({
        working: false,
        notice: format.toUpperCase() + ' generated by the school report service.',
      });
      return file;
    } catch (error) {
      this._setState({
        working: false,
        errorText: error instanceof ApiError ? error.message : error?.message ?? 'The report could not be downloaded.',
      });
      return null;
    }
  }
}

export default ReportsPresenter;
